// Regenerates web/src/ui/icons/lucide.ts, the icon catalogue's generated files and
// internal/iconset/names.json from an unpacked lucide-static package (OpenSpec changes
// ui-primitives, design D2, and icons-and-section-style). Dev-only and run by hand; the
// build never downloads anything. To add an interface icon, add its name to
// web/src/ui/icons/names.json; to add a choosable icon, add an entry to
// web/src/ui/icons/catalogue.json (never remove or rename one); then run:
//
//   npm pack lucide-static@1.48.0 && tar xzf lucide-static-1.48.0.tgz
//   node scripts/icons-sync.mjs ./package
import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const pkg = process.argv[2]
if (!pkg) {
  console.error('usage: node scripts/icons-sync.mjs <path to unpacked lucide-static package>')
  process.exit(2)
}
const out = new URL('../web/src/ui/icons/', import.meta.url).pathname
const version = JSON.parse(readFileSync(join(pkg, 'package.json'), 'utf8')).version
const names = JSON.parse(readFileSync(join(out, 'names.json'), 'utf8'))
const missing = []
const entries = names.map((name) => {
  let svg
  try {
    svg = readFileSync(join(pkg, 'icons', `${name}.svg`), 'utf8')
  } catch {
    missing.push(name)
    return ''
  }
  const inner = svg.slice(svg.indexOf('>', svg.indexOf('<svg')) + 1, svg.lastIndexOf('</svg>'))
    .split('\n').map((l) => l.trim()).filter(Boolean).join('')
  return `  ${JSON.stringify(name)}: ${JSON.stringify(inner)},`
})
if (missing.length) {
  console.error(`not in lucide-static ${version}: ${missing.join(', ')}`)
  process.exit(1)
}
writeFileSync(join(out, 'lucide.ts'), `// Generated by scripts/icons-sync.mjs from lucide-static ${version} (ISC, see
// LICENSE-lucide.txt). Do not edit by hand: add names to names.json and re-run.
export const ICONS = {
${entries.join('\n')}
} as const

export type IconName = keyof typeof ICONS

export const LUCIDE_VERSION = ${JSON.stringify(version)}
`)
writeFileSync(join(out, 'LICENSE-lucide.txt'), readFileSync(join(pkg, 'LICENSE'), 'utf8'))
console.log(`wrote ${names.length} icons from lucide-static ${version}`)

// The icon catalogue (OpenSpec change icons-and-section-style, design D2): the icons a
// person can choose for projects and sections. catalogue.json is curated by hand; from
// it this writes the path data of catalogue icons that are not interface icons (a lazy
// chunk), the compact list of names for the main bundle, and the server's copy of the
// names (internal/iconset, checked against catalogue.json by a Go test).
const catalogue = JSON.parse(readFileSync(join(out, 'catalogue.json'), 'utf8'))
const NAME = /^[a-z0-9-]{1,64}$/
const catalogueNames = catalogue.map((e) => e.name)
const bad = catalogueNames.filter((n) => !NAME.test(n))
if (bad.length) {
  console.error(`catalogue names must be lowercase letters, digits and hyphens: ${bad.join(', ')}`)
  process.exit(1)
}
const extra = []
for (const name of catalogueNames) {
  if (names.includes(name)) continue
  let svg
  try {
    svg = readFileSync(join(pkg, 'icons', `${name}.svg`), 'utf8')
  } catch {
    missing.push(name)
    continue
  }
  const inner = svg.slice(svg.indexOf('>', svg.indexOf('<svg')) + 1, svg.lastIndexOf('</svg>'))
    .split('\n').map((l) => l.trim()).filter(Boolean).join('')
  extra.push(`  ${JSON.stringify(name)}: ${JSON.stringify(inner)},`)
}
if (missing.length) {
  console.error(`catalogue icons not in lucide-static ${version}: ${missing.join(', ')}`)
  process.exit(1)
}
writeFileSync(join(out, 'catalogue.paths.ts'), `// Generated by scripts/icons-sync.mjs from lucide-static ${version} (ISC, see
// LICENSE-lucide.txt). Path data of catalogue icons that are not interface icons,
// loaded only through loadCatalogue(). Do not edit by hand.
export const CATALOGUE_PATHS: Record<string, string> = {
${extra.join('\n')}
}
`)
writeFileSync(join(out, 'catalogue.names.ts'), `// Generated by scripts/icons-sync.mjs from catalogue.json. Every catalogue name, so
// isCatalogueIcon() answers without loading the catalogue. Do not edit by hand.
export const CATALOGUE_NAMES = ${JSON.stringify([...catalogueNames].sort().join(' '))}
`)
const server = new URL('../internal/iconset/', import.meta.url).pathname
const serverEntries = catalogue.map((e) => JSON.stringify({ name: e.name, category: e.category, keywords: e.keywords }))
writeFileSync(join(server, 'names.json'), `[\n${serverEntries.join(',\n')}\n]\n`)
console.log(`wrote the catalogue: ${catalogueNames.length} icons, ${extra.length} outside the interface set`)
